public void postLoad()
{
    HcmPosition position = HcmPosition::findByPosition(this.PositionId);

    next postLoad();

    HcmPositionHierarchy positionHierarchy = HcmPositionHierarchy::findByPosition(position.RecId);

    this.QYGD_ParentPositionId  = HcmPosition::find(positionHierarchy.ParentPosition).PositionId;
}
